@import "tailwindcss";

/* Mise design tokens. Warm kitchen palette, herb-green accent.
   App is light; cook mode is dark (wrap it in .theme-cook). */
:root {
  --bg: #faf6ef;
  --surface: #ffffff;
  --surface-2: #f2ebe0;
  --ink: #221d17;
  --muted: #6b6155;
  --line: #e4dacb;
  --accent: #3d7a4b;
  --accent-ink: #ffffff;
  --accent-soft: #e3efe4;
  --warn: #b45309;
  --warn-soft: #fdf0dc;
  --danger: #b42318;
  --danger-soft: #fde8e6;
  --ai: #5b4bb7;
  --ai-soft: #ece9fb;
}

.theme-cook {
  --bg: #13110e;
  --surface: #1d1a16;
  --surface-2: #2a2621;
  --ink: #f7f2ea;
  --muted: #b9ae9f;
  --line: #3a342d;
  --accent: #7fc48f;
  --accent-ink: #10200f;
  --accent-soft: #23362a;
  --warn: #f5b04c;
  --warn-soft: #3a2b14;
  --danger: #ff8a7a;
  --danger-soft: #3d1c18;
  --ai: #b3a8ff;
  --ai-soft: #2a2546;
  background: var(--bg);
  color: var(--ink);
}

@theme inline {
  --color-bg: var(--bg);
  --color-surface: var(--surface);
  --color-surface-2: var(--surface-2);
  --color-ink: var(--ink);
  --color-muted: var(--muted);
  --color-line: var(--line);
  --color-accent: var(--accent);
  --color-accent-ink: var(--accent-ink);
  --color-accent-soft: var(--accent-soft);
  --color-warn: var(--warn);
  --color-warn-soft: var(--warn-soft);
  --color-danger: var(--danger);
  --color-danger-soft: var(--danger-soft);
  --color-ai: var(--ai);
  --color-ai-soft: var(--ai-soft);
  --font-sans: var(--font-inter);
  --font-display: var(--font-fraunces);
}

body {
  background: var(--bg);
  color: var(--ink);
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

dialog::backdrop {
  background: rgb(0 0 0 / 0.5);
}
import type { Metadata } from "next";
import { Fraunces, Inter } from "next/font/google";
import { ToastProvider } from "@/components/ui";
import "./globals.css";

const inter = Inter({ variable: "--font-inter", subsets: ["latin"] });
const fraunces = Fraunces({ variable: "--font-fraunces", subsets: ["latin"] });

export const metadata: Metadata = {
  title: "Chefly",
  description: "Scan your groceries, cook what expires first, hands-free.",
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html lang="en" className={`${inter.variable} ${fraunces.variable} h-full antialiased`}>
      <body className="min-h-full flex flex-col font-sans">
        <ToastProvider>{children}</ToastProvider>
      </body>
    </html>
  );
}
// Geometry for the hand-rolled /today charts. Pure.

/** Passes the chart palette validator on the app's surfaces; the --accent token reads too gray. */
export const CHART_COLOR = '#2e8540';

/** Smallest 1/2/5 × 10ⁿ at or above `value`, so the top axis label is a round number. */
export function niceCeil(value: number): number {
  if (!Number.isFinite(value) || value <= 0) return 100;
  const magnitude = 10 ** Math.floor(Math.log10(value));
  const step = [1, 2, 5, 10].find((s) => s * magnitude >= value) ?? 10;
    </>
  );
}

function drawLandmarks(c: HTMLCanvasElement | null, lm: Array<{ x: number; y: number }> | null) {
  const ctx = c?.getContext("2d");
  if (!c || !ctx) return;
  ctx.clearRect(0, 0, c.width, c.height);
  ctx.fillStyle = "#7fc48f";
  for (const p of lm ?? []) ctx.fillRect((1 - p.x) * c.width - 2, p.y * c.height - 2, 4, 4); // mirrored like the video
}

